package edu.powerbank;import edu.powerbank.bst.*;import edu.powerbank.queue.*;import edu.powerbank.linkedlist.*;import edu.powerbank.sorting.*;public class Main{public static void main(String[]args){var tree=new BinarySearchTree<Integer>();for(int x:new int[]{40,20,60,10,30})tree.insert(x);System.out.println("BST inorder: "+tree.inorder());var q=new CustomQueue<String>();q.enqueue("Reservation-101");q.enqueue("Reservation-102");System.out.println("Queue next: "+q.dequeue());var h=new CustomLinkedList<String>();h.add("Rental-1");h.add("Rental-2");System.out.println("History: "+h.toList());Integer[] a={5,1,4,2,8};Sorts.quick(a);System.out.println("Sorted: "+java.util.Arrays.toString(a));}}
